CREATE OR REPLACE FUNCTION calculate_market_risk(
    p_flow bigint,
    p_rate numeric,
    p_score numeric,
    p_count integer,
    p_lifespan integer
) RETURNS numeric AS $$
BEGIN
    RETURN ROUND((p_flow * (100 - p_rate) * (100 - p_score)) / 
                 NULLIF(p_count * p_lifespan, 0), 2);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_market_risk(
    p_flow bigint,
    p_rate numeric,
    p_score numeric,
    p_count integer,
    p_lifespan integer
) RETURNS numeric AS $$
BEGIN
    RETURN ROUND((p_flow * p_rate * p_score) / NULLIF(p_count * p_lifespan, 0), 2);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_market_risk(
    p_flow bigint,
    p_rate numeric,
    p_score numeric,
    p_count integer,
    p_lifespan integer
) RETURNS numeric AS $$
BEGIN
    RETURN ROUND((p_flow + p_rate + p_score) / NULLIF(p_count * p_lifespan, 0), 2);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_market_risk(
    p_flow bigint,
    p_rate numeric,
    p_score numeric,
    p_count integer,
    p_lifespan integer
) RETURNS numeric AS $$
BEGIN
    RETURN ROUND((p_flow / 1000.0) + (p_rate * 0.2) + (p_score * 0.3) + (p_count * 0.1) - (p_lifespan / 100.0), 2);
END;
$$ LANGUAGE plpgsql;
